components.css:
.ds-btn-cta {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  height: 40px; padding: 0 16px;
  background: #1f2937; color: #f9fafb;
  border: 1px solid #1f2937; border-radius: 10px;
  font: 600 14px/1 'Inter', system-ui, sans-serif;
  cursor: pointer;
  transition: background-color .2s cubic-bezier(.4,0,.2,1), border-color .2s;
}
.ds-btn-cta:hover { background: #111827; border-color: #111827; }
.ds-btn-cta:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; }
.ds-btn-cta:disabled { opacity: .4; pointer-events: none; }

.ds-btn-row {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  height: 32px; padding: 0 12px;
  background: transparent; color: #1a1d23;
  border: 1px solid transparent; border-radius: 10px;
  font: 600 12px/1 'Inter', system-ui, sans-serif;
  cursor: pointer;
  transition: background-color .15s cubic-bezier(.4,0,.2,1), color .15s;
}
.ds-btn-row:hover { background: #f9fafb; }
.ds-btn-row:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; }
.ds-btn-row.ds-active { background: #e5e7eb; }

.ds-btn-danger {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  height: 32px; padding: 0 12px;
  background: #dc2626; color: #ffffff;
  border: 1px solid #dc2626; border-radius: 10px;
  font: 600 12px/1 'Inter', system-ui, sans-serif;
  cursor: pointer;
  transition: background-color .15s cubic-bezier(.4,0,.2,1);
}
.ds-btn-danger:hover { background: #b91c1c; border-color: #b91c1c; }
.ds-btn-danger:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; }

.ds-btn-chip {
  display: inline-flex; align-items: center; justify-content: center; gap: 4px;
  height: 24px; padding: 0 8px;
  background: transparent; color: #1a1d23;
  border: 1px solid transparent; border-radius: 10px;
  font: 600 11px/1 'Inter', system-ui, sans-serif;
  cursor: pointer;
  transition: background-color .15s cubic-bezier(.4,0,.2,1);
}
.ds-btn-chip:hover { background: #f9fafb; }
.ds-btn-chip:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; }
.ds-btn-chip.ds-active { background: #6366f1; color: #fff; }

.ds-input {
  display: inline-flex; align-items: center;
  height: 40px; padding: 0 12px; width: 100%; max-width: 20rem;
  background: #ffffff; color: #1a1d23;
  border: 1px solid rgba(26,29,35,.2); border-radius: 10px;
  font: 400 14px/1 'Inter', system-ui, sans-serif;
  caret-color: #1a1d23;
}
.ds-input::placeholder { color: #1a1d23; opacity: .5; }
.ds-input:focus {
  outline: 2px solid #6366f1; outline-offset: 2px;
  border-color: #1a1d23;
}
.ds-input:disabled { background: #f9fafb; opacity: .5; cursor: not-allowed; }

.ds-card {
  background: #ffffff; color: #1a1d23;
  border: 1px solid #e5e7eb; border-radius: 10px;
  padding: 24px;
  /* No shadow. The hairline is the elevation. */
}
.ds-card-title {
  margin: 0 0 12px;
  font: 600 19.2px/1.3 'Inter', system-ui, sans-serif;
  letter-spacing: -0.01em;
}
.ds-card-body {
  margin: 0;
  font: 400 16px/1.55 'Inter', system-ui, sans-serif;
  color: rgba(26,29,35,.7);
}

.ds-badge {
  display: inline-flex; align-items: center; gap: 6px;
  height: 24px; padding: 0 8px;
  background: #f9fafb; color: #1a1d23;
  border: 1px solid #e5e7eb; border-radius: 6px;
  font: 500 12px/1 'Inter', system-ui, sans-serif;
}
.ds-swatch {
  width: 6px; height: 6px; border-radius: 999px; background: #6366f1; flex-shrink: 0;
}

.ds-nav {
  display: flex; align-items: center; gap: 8px; flex-wrap: nowrap;
  height: 48px; padding: 0 16px;
  background: #ffffff; border-bottom: 1px solid #e5e7eb;
}
.ds-wordmark {
  font: 620 21.6px/1 'Fraunces', Georgia, serif;
  letter-spacing: -0.03em; flex-shrink: 0;
  margin-right: 8px;
}
.ds-nav-links {
  display: flex; align-items: center; gap: 2px;
  flex: 1 1 0; min-width: 0; overflow-x: auto;
}
.ds-nav-link {
  display: inline-flex; align-items: center; gap: 6px;
  height: 32px; padding: 0 12px; border-radius: 10px;
  font: 600 12px/1 'Inter', system-ui, sans-serif;
  color: #1a1d23; text-decoration: none; white-space: nowrap;
  transition: background-color .15s;
}
.ds-nav-link:hover { background: #f9fafb; }
.ds-nav-link.ds-active { background: #e5e7eb; }
.ds-nav-link:focus-visible { outline: 2px solid #6366f1; outline-offset: 2px; }

.ds-table {
  width: 100%; border-collapse: separate; border-spacing: 0;
  border: 1px solid #e5e7eb; border-radius: 10px; overflow: hidden;
  font: 400 14px/1.55 'Inter', system-ui, sans-serif; color: #1a1d23;
}
.ds-table th {
  text-align: left; padding: 12px 16px;
  background: #ffffff;
  border-bottom: 1px solid #e5e7eb;
  font: 600 11px/1.2 'Inter', system-ui, sans-serif;
  letter-spacing: 0.08em; text-transform: uppercase;
  color: rgba(26,29,35,.6);
}
.ds-table td {
  padding: 12px 16px; border-bottom: 1px solid #e5e7eb;
}
.ds-table tbody tr:last-child td { border-bottom: none; }
.ds-table tbody tr:nth-child(even) { background: #f9fafb; }
.ds-num {
  font-family: 'JetBrains Mono', ui-monospace, monospace;
  font-variant-numeric: tabular-nums;
  font-size: .92em;
}
